<script setup>
import ContextHelp from '../shared/components/ContextHelp.vue'

import {computed, inject, onBeforeUnmount, ref} from 'vue'

import OptionPicker from '../shared/components/OptionPicker.vue'
import {toast} from '../shared/shadcnFeedback.js'
const props=defineProps({model:Object,item:Object,disabled:Boolean}),emit=defineEmits(['update:modelValue']),api=inject('api')
const open=ref(false),query=ref(''),source=ref(props.item?.source?.replace(/^zentao:/,'')||'manual'),sources=ref([]),mode=ref('default'),items=ref([]),busy=ref(false),error=ref(''),page=ref(1),cursor=ref(''),hasMore=ref(false),picked=ref('')
let sequence=0
const ownership=computed(()=>props.model.delivery_ownership||{mode:'self',work_item_id:props.item?.id,origin_work_item_id:props.item?.id})
function setMode(value){props.model.delivery_ownership={mode:value,origin_work_item_id:props.item.id,work_item_id:value==='self'?props.item.id:0};picked.value='';if(value==='follow'){open.value=true;load(true)}}
async function load(reset=false){const generation=++sequence;busy.value=true;error.value='';items.value=[];if(reset){page.value=1;cursor.value=''}try{if(!sources.value.length)sources.value=await api('api/research/work-items/sources');const params=new URLSearchParams({connection:source.value,product:'0',q:query.value,page:String(page.value),page_size:'20',cursor:cursor.value,status:mode.value==='active'?'active':'',main_candidate:mode.value==='default'?'1':'',relation:mode.value==='participating'?'participating':''});const data=await api('api/research/work-items/page?'+params);if(generation!==sequence)return;items.value=data.items.filter(w=>w.id!==props.item.id);cursor.value=data.next_cursor||'';hasMore.value=data.has_more;page.value=data.page}catch(e){if(generation===sequence){error.value=e.message;toast(e.message,'error')}}finally{if(generation===sequence)busy.value=false}}
async function select(w){if(busy.value)return;busy.value=true;try{const target=w.id?w:await api('api/research/work-items/attach',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({connection:w.source.slice(7),external_id:w.external_id})});props.model.delivery_ownership={mode:'follow',origin_work_item_id:props.item.id,work_item_id:target.id};picked.value=(target.external_id||'#'+target.id)+' · '+target.title;open.value=false}catch(e){toast(e.message,'error')}finally{busy.value=false}}
onBeforeUnmount(()=>sequence++)

import {Accordion,AccordionContent,AccordionItem,AccordionTrigger,Button,Field,FieldLabel,Input,Spinner} from '../shared/shadcn-ui.js'
</script>
<template><section class="space-y-3 border-t pt-5 md:col-span-2"><Field><div class="flex items-center gap-1"><FieldLabel>生产交付归属</FieldLabel><ContextHelp text="草稿可用于开发、测试。生产前需关联主项或在版本中明确选入。随主项交付保留当前 Bug 来源，不修改禅道父子关系。"/></div><OptionPicker :model-value="ownership.mode" :options="[{value:'self',label:'由当前工作项交付'},{value:'follow',label:'随其他工作项交付'},{value:'draft',label:'先保存草稿（开发／测试）'}]" :disabled="disabled||busy" @update:model-value="setMode"/></Field>
 <Accordion v-if="ownership.mode==='follow'" type="single" collapsible :model-value="open?'owner':''" @update:model-value="v=>{open=!!v;if(open)load(true)}"><AccordionItem value="owner"><AccordionTrigger :disabled="disabled||busy">{{picked||'主工作项 #'+(ownership.work_item_id||'待选择')}}</AccordionTrigger><AccordionContent class="space-y-3"><form class="grid gap-3 md:grid-cols-2" @submit.prevent="load(true)"><Input v-model="query" placeholder="搜索主项标题或编号" aria-label="搜索主工作项"/><OptionPicker v-model="source" :options="[...sources.map(s=>({value:s.name,label:s.name})),{value:'manual',label:'自定义工作项'}]" :disabled="busy" @change="load(true)"/><OptionPicker v-model="mode" :options="[{value:'default',label:'进行中及未上线'},{value:'active',label:'只看进行中'},{value:'participating',label:'我参与的'},{value:'all',label:'全部状态'}]" :disabled="busy" @change="load(true)"/><Button type="submit" variant="outline" :disabled="busy"><Spinner v-if="busy"/>搜索</Button></form>
 <div class="max-h-60 space-y-1 overflow-auto" :aria-busy="busy"><Button v-for="w in items" :key="w.source+':'+(w.external_id||w.id)" variant="ghost" class="h-auto w-full justify-start py-3 text-left" :disabled="busy" @click="select(w)"><span class="truncate">{{w.external_id||'#'+w.id}} · {{w.title}}</span></Button><p v-if="!items.length" class="p-3 text-sm text-muted-foreground">{{busy?'正在查询…':error||'没有匹配项，可切换状态或搜索编号'}}</p></div><Button variant="outline" :disabled="busy||!hasMore" @click="page++;load()">下一页</Button>
 </AccordionContent></AccordionItem></Accordion></section></template>
